import { configureStore } from '@reduxjs/toolkit'
import { authStore }      from './authStore/authStore';
import { counterSlice }   from './slices/counter/counterSlice';
import { globalStore }    from './globalStore/globalStore';
import { userStore }      from './userStore/userStore';
import { proveedoresStore } from './proveedoresStore/proveedoresStore';
import { departamentosMunicipiosStore } from './departamentosMunicipiosStore/departamentosMunicipiosStore';
import { preparacionStore } from './preparacionStore/preparacionStore';
import { trackerStore } from './trackerStore/trackerStore';
import { finalizadosStore } from './finalizadosStore/finalizadosStore';
import { archivadasStore } from './archivadasStore/archivadasStore';
import { clienteStore } from './clienteStore/clienteStore';
import { tramitesStore } from './tramitesStore/tramitesStore';
import { transitosTarifasStore } from './transitosTarifasStore/transitosTarifasStore';
import { liquidacionStore } from './liquidacionStore/liquidacionStore';

export const store = configureStore({
  reducer: {
    counter      : counterSlice.reducer,
    authStore    : authStore.reducer,
    globalStore  : globalStore.reducer,
    userStore    : userStore.reducer,
    proveedoresStore: proveedoresStore.reducer,
    departamentosMunicipiosStore: departamentosMunicipiosStore.reducer,
    preparacionStore: preparacionStore.reducer,
    trackerStore: trackerStore.reducer,
    finalizadosStore: finalizadosStore.reducer,
    archivadasStore: archivadasStore.reducer,
    clienteStore: clienteStore.reducer,
    tramitesStore: tramitesStore.reducer,
    transitosTarifasStore: transitosTarifasStore.reducer,
    liquidacionStore: liquidacionStore.reducer,
  }
})
